What is the output of the following JavaScript code snippet?

let sum = 0;
for (let i = 1; i <= 4; i++) {
  if (i === 3) continue;
  sum += i;
}
console.log(sum);

What value is printed by this JavaScript code snippet demonstrating closures?

function makeCounter() {
  let count = 0;
  return function() {
    return ++count;
  };
}
const counter = makeCounter();
counter();
console.log(counter());

How many times will the following loop execute?

int x = 5;
while (x > 0) {
  x -= 2;
}

What is the return value of `factorial(3)` given this function definition?

function factorial(n) {
  if (n <= 1) return 1;
  return n * factorial(n - 1);
}

What is the output of the following Java snippet?

class Animal {
  void sound() { System.out.print("Growl "); }
}
class Dog extends Animal {
  void sound() { System.out.print("Bark "); }
}
Animal pet = new Dog();
pet.sound();

